#include <iostream>

// Prints the square: parameter by value (a copy)
void printSquare(int n) {
    std::cout << n * n << std::endl;
}

// Changes the argument itself: parameter by reference
void boost(int& value, int delta = 1) {
    value += delta;
}

// Overload: same name, different parameter list
double average(double a, double b) {
    return (a + b) / 2;
}

double average(double a, double b, double c) {
    return (a + b + c) / 3;
}

int main() {
    printSquare(7);
    std::cout << average(3.0, 4.0) << std::endl;
    std::cout << average(1.0, 2.0, 6.0) << std::endl;

    int count = 10;
    boost(count);     // default delta = 1
    boost(count, 5);  // delta given explicitly
    std::cout << count << std::endl;
    return 0;
}

#include <iostream>

namespace physics {
    const double g = 9.81;
}

namespace geometry {
    const double g = 2.5;
}

int counter = 100; // global variable

void show() {
    int counter = 1; // local name shadows the global one
    std::cout << counter << ' ' << ::counter << std::endl;
}

int main() {
    show();
    std::cout << physics::g << ' ' << geometry::g << std::endl;

    {
        int inner = 7; // visible only between these braces
        std::cout << inner << std::endl;
    }
    // std::cout << inner; // error: no such name here
    std::cout << counter << std::endl;
    return 0;
}
